namespace Vitarish.Search.Contracts.Responses;
public enum SearchRetrievalModeDto { Exact = 1, Balanced = 2, Broad = 3 }
public sealed record SearchOptionsDto { public const int DefaultLimit = 20; public const int MaxLimit = 100; public int Skip { get; init; } public int Limit { get; init; } = DefaultLimit; public string? Type { get; init; } public string? TenantId { get; init; } public string? CorpusId { get; init; } public IReadOnlyDictionary<string,string> MetadataFilters { get; init; } = new Dictionary<string,string>(); public SearchRetrievalModeDto RetrievalMode { get; init; } = SearchRetrievalModeDto.Balanced; public double? MinScore { get; init; } public bool Explain { get; init; } public static int NormalizeLimit(int limit)=> limit<=0?DefaultLimit:Math.Min(limit,MaxLimit); }
public sealed record SearchDocumentDto { public required string Id { get; init; } public required string Title { get; init; } public string? Body { get; init; } public string? SemanticText { get; init; } public required string TenantId { get; init; } public required string Type { get; init; } public string? NavigationUrl { get; init; } public string? IndexName { get; init; } public double? Score { get; init; } public IReadOnlyDictionary<string, object?> Metadata { get; init; } = new Dictionary<string, object?>(); }
public sealed record SearchDiagnosticsDto { public SearchRetrievalModeDto RetrievalMode { get; init; } public IReadOnlyList<string> AppliedStrategies { get; init; } = []; public IReadOnlyDictionary<string, object?> Data { get; init; } = new Dictionary<string, object?>(); }
public sealed record SearchResultDto { public required IReadOnlyList<SearchDocumentDto> Items { get; init; } public required long TotalCount { get; init; } public required string Query { get; init; } public SearchDiagnosticsDto? Diagnostics { get; init; } }
public sealed record SearchIndexStatusReportDto { public required string IndexName { get; init; } public long DocumentCount { get; init; } public long StoreSizeBytes { get; init; } }
public enum SearchPriorityTierDto { Low = 0, Normal = 1, High = 2, Critical = 3 }
public sealed record SearchExactMatchPolicyDto { public bool IsExactMatchFirst { get; init; } public IReadOnlyList<string> FieldNames { get; init; } = []; public SearchPriorityTierDto PriorityTier { get; init; } = SearchPriorityTierDto.Normal; }
public sealed record SearchIndexPolicyReportDto { public required string IndexName { get; init; } public required SearchExactMatchPolicyDto ExactMatchPolicy { get; init; } }
public sealed record SearchCommandResult(bool Succeeded, string? Error = null);
